text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Nisha. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hello Nisha, mera bill bahut zyada aaya hai is baar. I am very upset, please check karo kya hua hai.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am sorry to hear that you are frustrated with your bill. I will definitely look into this for you.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "agent",
      "text": "Before we proceed, could you please provide your account number and date of birth for verification?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Haan, my account number is 68526005 and my date of birth is 07/02/1997. My name is Aisha Nair and my phone is 98293 22901.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Ms. Nair. Let me check the charges. One moment please.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Please jaldi check karo, it is too much money for a simple plan.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I see here that you were charged twice for the international roaming pack. This was an error on our end.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Exactly! Maine toh sirf ek pack liya tha. Please fix this immediately.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I will raise a refund request for the wrong charge right now.",
      "tags": [
        "action:refund_request"
      ]
    },
    {
      "speaker": "agent",
      "text": "Please note that the refund is subject to approval and usually takes 7-10 business days to reflect in your account.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "Theek hai, I understand. Thank you for finding the mistake.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "You are welcome. Is there anything else I can assist you with today?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Nahi, that is all. Thank you, Nisha.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Thank you for choosing Nimbus Telecom. I have raised the refund request, and you will receive an update soon. Goodbye!",
      "tags": [
        "closure"
      ]
    }
  ]
}
